#!/usr/bin/env node
/**
 * Guard against hardcoded design values in component CSS.
 *
 * Design values (colors, spacing, radii, etc.) must come from `--cq-*` tokens
 * generated by @croquis/tokens — never raw literals. This is the machine-checked
 * enforcement of Croquis's "no hardcoded CSS" rule.
 *
 * Rules (in the scanned component CSS, NOT the generated token sheet):
 *   1. No raw color literals: #hex, rgb()/rgba()/hsl()/hsla()/hwb()/lab()/lch()/oklch()/oklab().
 *   2. No raw absolute/root length units (px/rem/em/pt) outside @media/@container/@supports
 *      preludes — use tokens. Viewport units (vw/vh/vmin/vmax) and % are allowed.
 *
 * Values inside `var(--cq-...)` are always allowed. Zero dependencies.
 */
import { existsSync, readdirSync, readFileSync, statSync } from 'node:fs';
import { join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const repoRoot = fileURLToPath(new URL('..', import.meta.url));

const SCAN_DIRS = ['packages/dashboard/src', 'packages/widget/src'];
// Generated or vendored files that legitimately hold raw values.
const IGNORE = [/tokens\.css$/, /generated\//, /node_modules\//, /dist\//];

const COLOR_HEX = /#[0-9a-fA-F]{3,8}\b/;
const COLOR_FN = /\b(rgb|rgba|hsl|hsla|hwb|lab|lch|oklch|oklab)\s*\(/i;
const LENGTH = /(?<![\w.#-])\d*\.?\d+(px|rem|em|pt)\b/i;
const AT_RULE_WITH_LENGTHS = /^\s*@(media|container|supports)\b/;

/** Recursively collect *.css files under a directory. */
function collectCss(dir) {
  const out = [];
  if (!existsSync(dir)) return out;
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) out.push(...collectCss(full));
    else if (entry.endsWith('.css')) out.push(full);
  }
  return out;
}

/** Remove `var( ... )` groups (balanced parens) so their contents are ignored. */
function stripVar(value) {
  let out = '';
  let i = 0;
  while (i < value.length) {
    const idx = value.indexOf('var(', i);
    if (idx === -1) {
      out += value.slice(i);
      break;
    }
    out += value.slice(i, idx);
    let depth = 0;
    let j = idx + 3;
    for (; j < value.length; j++) {
      if (value[j] === '(') depth++;
      else if (value[j] === ')') {
        depth--;
        if (depth === 0) {
          j++;
          break;
        }
      }
    }
    i = j;
  }
  return out;
}

/** Strip /* ... *\/ comments while preserving line breaks. */
function stripComments(css) {
  return css.replace(/\/\*[\s\S]*?\*\//g, (m) => m.replace(/[^\n]/g, ' '));
}

const violations = [];

for (const rel of SCAN_DIRS) {
  const dir = join(repoRoot, rel);
  for (const file of collectCss(dir)) {
    if (IGNORE.some((re) => re.test(file))) continue;
    const source = stripComments(readFileSync(file, 'utf8'));
    const lines = source.split('\n');
    lines.forEach((line, index) => {
      const isAtRulePrelude = AT_RULE_WITH_LENGTHS.test(line);
      const scannable = stripVar(line);
      const report = (rule, match) =>
        violations.push({
          file: relative(repoRoot, file),
          line: index + 1,
          rule,
          match,
          text: line.trim(),
        });

      const hex = COLOR_HEX.exec(scannable);
      if (hex) report('raw-color-hex', hex[0]);
      const fn = COLOR_FN.exec(scannable);
      if (fn) report('raw-color-function', fn[0]);
      if (!isAtRulePrelude) {
        const len = LENGTH.exec(scannable);
        if (len) report('raw-length', len[0]);
      }
    });
  }
}

if (violations.length > 0) {
  console.error(`\n✖ Found ${violations.length} hardcoded CSS value(s) — use --cq-* tokens:\n`);
  for (const v of violations) {
    console.error(`  ${v.file}:${v.line}  [${v.rule}: ${v.match}]  ${v.text}`);
  }
  console.error('');
  process.exit(1);
}

console.log('✓ No hardcoded CSS values found (component CSS uses --cq-* tokens).');
